 function shortSummary(s){const r=B.evaluate('plan',s);const name=goalName(s);if(!r.valid)return 'Obiettivo: '+name+' · piano da completare ('+r.reason+')';return 'Obiettivo: '+name+' · '+(r.totalSessions===0||(r.continuous&&r.totalMinutes===0)?'già possibile':r.continuous?timeText(r):plural(r.totalSessions,' partita',' partite')+' da '+sessionLabel(s)+' · '+plural(r.days,' giorno',' giorni'))+' · '+(s.plan.source==='missions'?plural(s.plan.missions.length,' missione',' missioni'):money(s.plan.situation.hourly)+'/h')+(r.purchases.some(x=>x.atSession)?' · '+plural(r.purchases.filter(x=>x.atSession).length,' acquisto',' acquisti')+' da fare prima':'');}
